package io.github.jesterportfolio.hearth.gathering;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GatheringFacilitiesTest {
    static Map<String,Object> site(String id,String action,int x){return new HashMap<>(Map.of("id",id,"title","공개 현장 시설","action",action,"x",x,"y",64,"z",0,"material","STONE_BUTTON"));}
    static Map<String,Object> root(){return new HashMap<>(Map.of("format",1,"isolated-prototype",true,"gathering-id","public_gathering","sites",new ArrayList<>(List.of(site("entry","ENTER",5),site("exit","LEAVE",-1)))));}
    static GatheringFacilities parse(Map<?,?> root){return GatheringFacilities.parse(root,GatheringDungeonTest.content());}
    static GatheringFacilities.Stamp stamp(Object session,boolean member){return new GatheringFacilities.Stamp(UUID.fromString("00000000-0000-0000-0000-000000000001"),session,UUID.fromString("00000000-0000-0000-0000-000000000002"),1,2,3,GatheringStore.Phase.OPEN,member,false);}
    @Test void entryAndExitHaveIndependentChoicesAndNeedOnSitePermission(){var c=parse(root());var token=new Object();var s=stamp(token,false);var entry=c.sites().getFirst();var exit=c.sites().getLast();var shown=c.choose(entry,s,true);c.require(shown,entry,s,true);assertThrows(IllegalStateException.class,()->c.choose(exit,s,true));assertThrows(IllegalStateException.class,()->c.choose(entry,s,false));assertNotNull(c.choose(exit,stamp(token,true),true));assertThrows(IllegalStateException.class,()->c.require(shown,exit,stamp(token,true),true));assertTrue(exit.near(.5,64,.5));assertFalse(entry.near(100,64,100));}
    @Test void sessionRunWorldGenerationRevisionPhaseMembershipAndPendingChangesRejectOldChoice(){var c=parse(root());var entry=c.sites().getFirst();var s=stamp(new Object(),false);var shown=c.choose(entry,s,true);var changes=List.of(new GatheringFacilities.Stamp(UUID.randomUUID(),s.session(),s.world(),1,2,3,s.phase(),false,false),new GatheringFacilities.Stamp(s.run(),new Object(),s.world(),1,2,3,s.phase(),false,false),new GatheringFacilities.Stamp(s.run(),s.session(),UUID.randomUUID(),1,2,3,s.phase(),false,false),new GatheringFacilities.Stamp(s.run(),s.session(),s.world(),2,2,3,s.phase(),false,false),new GatheringFacilities.Stamp(s.run(),s.session(),s.world(),1,3,3,s.phase(),false,false),new GatheringFacilities.Stamp(s.run(),s.session(),s.world(),1,2,4,s.phase(),false,false),new GatheringFacilities.Stamp(s.run(),s.session(),s.world(),1,2,3,GatheringStore.Phase.ERROR_HOLD,false,false),new GatheringFacilities.Stamp(s.run(),s.session(),s.world(),1,2,3,GatheringStore.Phase.RESETTING,false,false),new GatheringFacilities.Stamp(s.run(),s.session(),s.world(),1,2,3,s.phase(),true,false),new GatheringFacilities.Stamp(s.run(),s.session(),s.world(),1,2,3,s.phase(),false,true));for(var fresh:changes)assertThrows(IllegalStateException.class,()->c.require(shown,entry,fresh,true));}
    @SuppressWarnings("unchecked") @Test void duplicateWrongDungeonResetAreaAndUnsupportedBlocksFailBeforeActivation(){for(String bad:List.of("duplicate","inside","far_exit","material","dungeon")){var r=root();var rows=(List<Map<String,Object>>)r.get("sites");switch(bad){case "duplicate"->rows.get(1).put("id","entry");case "inside"->rows.get(0).put("x",0);case "far_exit"->rows.get(1).put("x",30);case "material"->rows.get(0).put("material","CHEST");case "dungeon"->r.put("gathering-id","other");}assertThrows(IllegalArgumentException.class,()->parse(r));}assertThrows(UnsupportedOperationException.class,()->parse(root()).sites().clear());}
}
